extra_sources['escapement-airy']=('George Biddell Airy · On the disturbances of pendulums and balances, and on the theory of escapements, Trans. Cambridge Phil. Soc. 3 (1830)','https://theindex.nawcc.org/Articles/AiryOnPendulumsAndBalanceWheels.htm')
